import { HealStep } from "../../types/equipables/maneuvers.ts";
import { ActionCtx } from "../../types/events/actionCtx.ts";
import { limitToBounds, trunc } from "../utils/battle.ts";
import { weaponMap } from "../../shared/definitions/weapons/sets.ts";
import { getBaseWeaponValue, getModifiedWeaponValue } from "./weaponScaling.ts";

/**
 * Computes the total heal generated by the source character, before it is
 * split across targets. Scales off the equipped weapon's power the same way
 * damage does, using `healType` to select which stats/affinities apply.
 * Heals can't miss, so there's no accuracy roll involved.
 */
export const calcHeal = (ctx: ActionCtx, step: HealStep) => {
  const { characters, sourceId } = { ...ctx };
  const source = characters[sourceId];

  if (!source) {
    return 0;
  }

  const stats = source.stats;
  const weaponName = source?.equipped.weapon;
  const weapon = weaponName && weaponMap.get(weaponName);

  if (!weapon) {
    return 0;
  }

  const baseHeal = getBaseWeaponValue(weapon);
  const modifiedHeal = getModifiedWeaponValue(weapon, step.healType, stats);
  return (baseHeal + modifiedHeal) * step.strength;
};

export const handleHeal = (ctx: ActionCtx, step: HealStep) => {
  const { targetIds, instance } = ctx;

  if (!targetIds || targetIds.length === 0) {
    return ctx;
  }

  const totalHeal = trunc(calcHeal(ctx, step));
  ctx.heal = totalHeal * targetIds.length;

  targetIds.forEach((targetId) => {
    const existingInstance = instance.get(targetId);
    if (existingInstance) {
      existingInstance.heal = (existingInstance.heal || 0) + totalHeal;
    }
  });

  return ctx;
};

export const applyHeal = (ctx: ActionCtx) => {
  const { characters, instance, messages } = { ...ctx };

  instance.forEach((instanceDtl, targetId) => {
    if (!instanceDtl.heal) {
      return;
    }

    const character = characters[targetId];
    if (character?.stats?.core) {
      const { life, maxLife } = character.stats.core;
      const healedLife = limitToBounds(life + instanceDtl.heal, maxLife);
      const appliedHeal = healedLife - life;
      character.stats.core.life = healedLife;
      messages.steps?.push(
        `Healed ${characters[targetId].name} for ${appliedHeal}.`,
      );
    }
  });

  return ctx;
};
